// Authored content for 3.1.5.2 Gas exchange systems. Spec statements s1–s7 (OxfordAQA 9610 v5.1).
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.gasxArt;
  const R = "3.1.5.2";
  const P = (slot) => window.BIO.views.photo(slot);
  // Illustrative datasets for the lung-disease data interpretation interactive (constructed to match the direction and
  // approximate magnitude of effects described in respiratory medicine texts; NOT patient records).
  const datasets = [
    { title: "Dataset A (illustrative): spirometry in a healthy adult and in two lung conditions", html: `<table class="tbl"><thead><tr><th></th><th>Healthy adult</th><th>Condition X (airways narrowed and inflamed)</th><th>Condition Y (alveolar walls thickened and stiff)</th></tr></thead><tbody><tr><th>Forced vital capacity, FVC / dm³</th><td>4.8</td><td>4.4</td><td>2.9</td></tr><tr><th>Volume breathed out in the first second, FEV₁ / dm³</th><td>3.9</td><td>2.4</td><td>2.5</td></tr><tr><th>FEV₁ ÷ FVC</th><td>0.81</td><td>0.55</td><td>0.86</td></tr><tr><th>Breathing rate at rest / breaths min⁻¹</th><td>14</td><td>18</td><td>24</td></tr><tr><th>Tidal volume at rest / dm³</th><td>0.50</td><td>0.48</td><td>0.30</td></tr></tbody></table><p class="tiny muted">FVC = the most air that can be breathed out after the deepest breath in. FEV₁ = the volume of that air expelled in the first second. Values chosen to illustrate obstructive (X) and restrictive (Y) patterns.</p>` },
    { title: "Dataset B (illustrative): oxygen uptake and alveolar measurements", html: `<table class="tbl"><thead><tr><th></th><th>Healthy adult</th><th>Condition Y (thickened alveolar walls)</th><th>Condition Z (alveolar walls broken down into larger sacs)</th></tr></thead><tbody><tr><th>Mean thickness of alveolar wall + capillary / µm</th><td>0.6</td><td>2.4</td><td>0.6</td></tr><tr><th>Total alveolar surface area / m²</th><td>70</td><td>65</td><td>30</td></tr><tr><th>Arterial blood pO₂ at rest / kPa</th><td>13.0</td><td>9.5</td><td>9.0</td></tr><tr><th>Maximum oxygen uptake in exercise / dm³ min⁻¹</th><td>3.2</td><td>1.4</td><td>1.3</td></tr></tbody></table><p class="tiny muted">Values illustrative; the healthy figures are standard textbook magnitudes.</p>` },
  ];
  window.BIO.content[R] = {
    status: "reviewed",
    banner: "alveoli-lm", bannerText: "Five gas exchange surfaces, one set of principles: large area, short distance, steep gradient, and the cost in water.",
    keywords: ["gas exchange", "diffusion", "single-celled", "tracheal system", "spiracle", "trachea", "tracheole", "leaf", "stomata", "guard cells", "spongy mesophyll", "air spaces", "xerophyte", "xerophytic", "water loss", "cuticle", "trachea", "bronchi", "bronchioles", "lungs", "alveoli", "alveolar epithelium", "capillary", "ventilation", "breathing", "diaphragm", "intercostal", "inspiration", "expiration", "pressure", "volume", "lung disease", "FEV1", "spirometry"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.1.5.2).</strong> (1) Adaptations of gas exchange surfaces in the body surface of a single-celled organism, the tracheal system of an insect and the leaves of a dicotyledonous plant. (2) The compromise between efficient gas exchange and limiting water loss in terrestrial insects and in xerophytic plants. (3) The gross structure of the human gas exchange system, <em>limited to</em> alveoli, bronchioles, bronchi, trachea and lungs. (4) The essential features of the alveolar epithelium and its capillaries as a surface for gas exchange. (5) The mechanism of breathing: roles of the diaphragm and intercostal muscles in producing pressure and volume changes in the thoracic cavity. You should be able to (6) use the principles of gas exchange to identify and explain adaptations of <em>unfamiliar</em> surfaces and (7) interpret data on the effects of lung disease on gas exchange and ventilation. <em>Not required by OxfordAQA:</em> fish gills, the detailed structure of cartilage/smooth muscle in the airways, named lung diseases, the chemistry of surfactant. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span></div>
<h2 data-stmt="${R}.s6 ${R}.s1">1. The principles that every surface obeys <span class="badge teal">required</span></h2>
<p>Gas exchange is by <strong>diffusion</strong>, so every efficient surface shows the same features (3.1.4.2): a <strong>large surface area</strong> relative to the organism's volume; a <strong>thin</strong> barrier (short diffusion distance); a <strong>steep concentration gradient</strong>, maintained by moving the air or water (ventilation) and/or moving the blood; and, because gases dissolve before they cross cell membranes, a <strong>moist</strong> surface. The last feature creates the central problem for land organisms: a moist surface exposed to air loses water by evaporation, so efficient gas exchange and limiting water loss are in <strong>conflict</strong>.</p>
<h2 data-stmt="${R}.s1">2. Single-celled organisms <span class="badge teal">required</span></h2>
<div class="grid grid-2">${A.singleCell()}<div><ul><li>A bacterium is a few micrometres across, and even a large amoeba is less than a millimetre long and flattened, so its <strong>surface area to volume ratio is very large</strong> and its <strong>diffusion distance is short</strong>: no part of the cytoplasm is far from the surface.</li><li>Oxygen diffuses in across the <strong>cell-surface membrane</strong> (the whole body surface is the exchange surface) and carbon dioxide diffuses out; the gradients are maintained by respiration inside and by the surrounding water.</li><li>No specialised surface and no transport system are needed. Oxygen reaches the mitochondria, and the cell's needs are met, by diffusion alone.</li></ul></div></div>
<h2 data-stmt="${R}.s1 ${R}.s2">3. Insects: the tracheal system <span class="badge teal">required</span></h2>
<p>Insects are larger and have a waterproof exoskeleton, so their body surface cannot be the exchange surface. Instead, air is piped directly to the tissues:</p>
<ul><li><strong>Spiracles</strong>: openings along the thorax and abdomen with <strong>valves</strong> that open and close.</li><li><strong>Tracheae</strong>: air-filled tubes running inwards from the spiracles, held open by rings of <strong>chitin</strong>.</li><li><strong>Tracheoles</strong>: very fine, thin-walled branches (no chitin) that run between and into the cells; their ends contain <strong>fluid</strong>.</li></ul>
<p><strong>How gases move.</strong> Respiring cells use oxygen, so the concentration of oxygen at the tracheole ends is low and a gradient runs from the air outside, through the spiracle and along the tracheae and tracheoles: oxygen <strong>diffuses</strong> along the tubes and dissolves in the fluid at the end before diffusing into the cells. Carbon dioxide diffuses the other way. The diffusion distance from a tracheole to a cell is tiny. In larger or active insects, movements of the abdomen compress and expand the tracheae (<strong>ventilation</strong>), moving air in and out in bulk, which steepens the gradients. <span class="badge">supporting</span> During vigorous activity, lactate accumulating in muscle lowers its water potential; water moves out of the tracheole ends into the muscle, so air penetrates further and the diffusion distance shortens exactly when demand is highest. Insect blood (haemolymph) carries nutrients but little or no oxygen: gas exchange does not depend on it.</p>
<p><strong>The water-loss compromise.</strong> Every open spiracle is a hole in a waterproof body through which water vapour escapes. Insects limit the loss by <strong>closing the spiracle valves</strong> when oxygen demand is low (many open them only intermittently), by <strong>hairs</strong> around the spiracles that trap a layer of humid air, and by the waterproof <strong>cuticle</strong> everywhere else. The cost is a lower rate of gas exchange; the trade-off is set by activity.</p>
${P("insect-tracheae")}
<h2 data-stmt="${R}.s1">4. Dicotyledonous leaves <span class="badge teal">required</span></h2>
<p>A leaf exchanges carbon dioxide and oxygen for photosynthesis (by day) and respiration (always). It has no transport system for gases; diffusion does everything, and the structure makes that possible:</p>
<ul><li><strong>Thin, flat shape</strong> (large SA : V) so no cell is far from the air.</li><li><strong>Stomata</strong>: pores, mostly in the lower epidermis, each bounded by two <strong>guard cells</strong>. Guard cells change shape with their turgor: when they take up water they bend apart and the pore opens; when they lose water it closes. Open stomata let CO₂ diffuse in down the gradient created by photosynthesis, and O₂ and water vapour diffuse out.</li><li><strong>Intercellular air spaces</strong> in the <strong>spongy mesophyll</strong>: a continuous network from the stomata to every mesophyll cell, so gases diffuse quickly through air rather than slowly through cells.</li><li><strong>Spongy mesophyll cells</strong> with thin, moist walls present a <strong>very large total surface</strong> to the air spaces; gases dissolve in the surface film and diffuse across the membrane into the cytoplasm and chloroplasts.</li><li>The gradient is maintained by photosynthesis using CO₂ in the palisade and spongy cells (and respiration producing it at night).</li></ul>
<div class="grid grid-2">${P("leaf-section-lm")}${P("stomata-lm")}</div>
<h2 data-stmt="${R}.s2">5. Xerophytic plants: gas exchange against water loss <span class="badge teal">required</span></h2>
<p>Every open stoma that admits CO₂ also lets water vapour out. For a plant in a hot, dry, windy or salty habitat (a <strong>xerophyte</strong>) water loss can exceed uptake, so xerophytes have adaptations that reduce the rate of transpiration while still allowing some gas exchange. All of them act on Fick's law: they lower the water potential gradient between leaf and air, reduce the area of surface exposed, or lengthen the pathway.</p>
<table><tr><th>Adaptation</th><th>How it limits water loss</th><th>Example</th></tr>
<tr><th>Thick waxy cuticle</th><td>Waterproofs the epidermis so that loss is confined to the stomata</td><td>Holly, many evergreen leaves</td></tr>
<tr><th>Stomata sunken in pits or grooves</th><td>Still, humid air collects in the pit, so the water potential gradient from leaf to air is shallow; diffusion of water out is slower</td><td>Marram grass, pine</td></tr>
<tr><th>Hairs on the leaf surface</th><td>Trap a layer of humid, still air next to the stomata (same effect as pits)</td><td>Marram grass, lamb's ear</td></tr>
<tr><th>Rolled leaves (stomata on the inside)</th><td>Enclose a humid space; hinge cells lose turgor in dry weather and roll the leaf tighter</td><td>Marram grass</td></tr>
<tr><th>Fewer or smaller stomata; stomata close at the hottest time of day</th><td>Fewer pores through which vapour can leave; less exchange when the gradient is steepest</td><td>Many succulents, cacti</td></tr>
<tr><th>Small, needle-like leaves or spines</th><td>Reduce the total surface area from which water evaporates</td><td>Pine, cacti (stem photosynthesises)</td></tr></table>
<p>The compromise is explicit: each adaptation also slows the diffusion of CO₂ in, so xerophytes often grow more slowly. <span class="badge amber">extension</span> Some (CAM plants such as cacti) open their stomata only at night and store CO₂ as an organic acid for use by day.</p>
${P("marram-leaf-section")}
<h2 data-stmt="${R}.s3 ${R}.s4">6. The human gas exchange system <span class="badge teal">required</span></h2>
<p>Humans are large, active and warm-blooded, with a small SA : V. The gross structure that the specification requires:</p>
<ul><li><strong>Lungs</strong>: a pair of lobed organs in the thorax, enclosed by the ribs and the diaphragm.</li><li><strong>Trachea</strong>: the airway from the throat to the chest, held open by C-shaped rings of cartilage; lined with ciliated epithelium and mucus-producing goblet cells that trap and remove particles (<span class="badge">supporting</span>).</li><li><strong>Bronchi</strong>: the trachea divides into two bronchi, one to each lung, also supported by cartilage.</li><li><strong>Bronchioles</strong>: the bronchi branch repeatedly into narrower bronchioles with walls of smooth muscle (which can constrict or dilate the airway) and no cartilage.</li><li><strong>Alveoli</strong>: the bronchioles end in clusters of tiny air sacs, about 300 million in two lungs, giving a total exchange surface of roughly 70 m² (<span class="badge">supporting</span>: a standard estimate).</li></ul>
${A.humanSystem()}
<h3>The alveolar epithelium and its capillaries <span class="badge teal">required</span></h3>
<ul><li>Each alveolus is lined by a single layer of flattened (<strong>squamous</strong>) epithelial cells, so the wall is extremely thin.</li><li>A dense network of <strong>capillaries</strong> is pressed against the outside of the alveoli; capillary walls are also one endothelial cell thick. The total barrier between air and blood, epithelium plus endothelium, is about 0.5–1 µm: a <strong>very short diffusion distance</strong>.</li><li>The vast number of alveoli gives a <strong>large surface area</strong>; the capillary network gives a large area of contact with the blood.</li><li><strong>Steep gradients</strong> are maintained in two ways: <strong>ventilation</strong> keeps replacing the air in the alveoli (high pO₂, low pCO₂), and <strong>blood flow</strong> keeps bringing deoxygenated blood (low pO₂, high pCO₂) and carrying oxygenated blood away. Red blood cells pass in single file, slowing and flattening against the wall, and haemoglobin removes oxygen from solution, keeping the plasma pO₂ low.</li><li>The epithelium is <strong>moist</strong>: gases dissolve in the film before diffusing across. (<span class="badge amber">extension</span>: a surfactant in the film lowers surface tension and stops the alveoli collapsing.)</li></ul>
<p>Oxygen therefore diffuses from the alveolar air into the blood, and carbon dioxide from the blood into the alveolar air, each down its own partial-pressure gradient.</p>
${P("alveoli-lm")}
<h2 data-stmt="${R}.s5">7. The mechanism of breathing (ventilation) <span class="badge teal">required</span></h2>
<p>Ventilation moves air in and out of the lungs by changing the <strong>volume</strong> of the thoracic cavity, which changes the <strong>pressure</strong> inside the lungs relative to the atmosphere. Air always flows from higher to lower pressure.</p>
<table><tr><th></th><th>Inspiration (breathing in)</th><th>Expiration (breathing out)</th></tr>
<tr><th>Diaphragm</th><td><strong>Contracts</strong>: flattens and moves down</td><td><strong>Relaxes</strong>: returns to its dome shape (pushed up by the abdominal organs)</td></tr>
<tr><th>Intercostal muscles</th><td><strong>External</strong> intercostals contract: ribs move <strong>up and out</strong></td><td>External intercostals relax: ribs move down and in under their own weight. In <strong>forced</strong> expiration the <strong>internal</strong> intercostals contract and pull the ribs down and in, and abdominal muscles push the diaphragm up</td></tr>
<tr><th>Volume of thoracic cavity</th><td>Increases</td><td>Decreases</td></tr>
<tr><th>Pressure in the lungs</th><td>Falls <strong>below</strong> atmospheric pressure</td><td>Rises <strong>above</strong> atmospheric pressure</td></tr>
<tr><th>Air movement</th><td>Air flows <strong>in</strong> down the pressure gradient</td><td>Air flows <strong>out</strong> down the pressure gradient</td></tr>
<tr><th>Energy</th><td><strong>Active</strong>: muscle contraction</td><td>Quiet expiration is largely <strong>passive</strong> (elastic recoil of the lungs); forced expiration is active</td></tr></table>
<div class="notice amber"><strong>Precision matters here.</strong> Say "pressure in the lungs falls below atmospheric so air moves in", not "the lungs suck air in". Inspiration is always active; normal expiration is passive, and only forced expiration involves the internal intercostals. The two sets of intercostal muscles are <strong>antagonistic</strong>: external contract on inspiration, internal on forced expiration. The lungs have no muscle that can inflate them; they expand only because the thorax does.</div>
<h2 data-stmt="${R}.s7">8. Interpreting data on lung disease <span class="badge teal">required</span></h2>
<p>The specification asks you to <em>interpret data</em>, not to learn a list of diseases. Any condition affects gas exchange or ventilation through the same principles:</p>
<ul><li><strong>Thickening of the alveolar wall</strong> (scarring, fluid, fibrous tissue): longer diffusion distance, slower exchange; the lungs become stiff, so the volume moved per breath falls and breathing rate rises.</li><li><strong>Loss of alveolar surface</strong> (walls break down into larger sacs; loss of elastic tissue): smaller area, slower exchange; air is also harder to expel.</li><li><strong>Narrowing of the airways</strong> (inflammation, mucus, muscle constriction): higher resistance to airflow, especially on expiration; the volume that can be forced out in one second (FEV₁) falls much more than the total capacity (FVC).</li><li><strong>Reduced blood flow</strong> or a poor match between ventilation and blood flow: gradients collapse even if the surface is intact.</li></ul>
<p>Useful measurements: <strong>tidal volume</strong> (air per breath), <strong>breathing rate</strong>, <strong>ventilation rate</strong> = tidal volume × breathing rate, <strong>FVC</strong> (forced vital capacity) and <strong>FEV₁</strong> (volume expelled in the first second), the ratio FEV₁ ÷ FVC, and the partial pressure of oxygen in arterial blood. When interpreting, link each change to area, distance, gradient or airflow, quote figures, and consider whether the data distinguish between possible causes.</p>`,
    diagrams: [
      { id: "d-3.1.5.2-1", title: "Single-celled organism: exchange across the body surface", status: "reviewed", caption: "Oxygen diffuses in and carbon dioxide out across the whole cell-surface membrane; large SA : V and a short diffusion distance mean no special surface or transport system is needed. Schematic.", alt: "A single cell with arrows showing oxygen entering across the whole surface and carbon dioxide leaving.", svg: A.singleCell() },
      { id: "d-3.1.5.2-2", title: "Insect tracheal system", status: "reviewed", caption: "Spiracles (with valves) open into tracheae (chitin rings) that branch into fine tracheoles ending in fluid among the muscle fibres; gases diffuse along the tubes directly to the cells. Schematic section.", alt: "Section through an insect showing spiracles in the body wall, a trachea with rings, tracheoles branching to muscle fibres, and arrows for oxygen in and carbon dioxide out.", svg: A.insectTracheal() },
      { id: "d-3.1.5.2-3", title: "Dicotyledonous leaf in section", status: "reviewed", caption: "Cuticle and epidermis above and below; palisade mesophyll; spongy mesophyll with intercellular air spaces; vascular bundle (xylem above phloem); stomata with guard cells in the lower epidermis; CO₂ in, O₂ and water vapour out. Schematic transverse section.", alt: "Transverse section of a leaf with labelled layers, air spaces and two open stomata with arrows.", svg: A.leafSection() },
      { id: "d-3.1.5.2-4", title: "Mesophyte and xerophyte leaves compared", status: "reviewed", caption: "A flat mesophytic leaf with exposed stomata beside a rolled marram-type leaf with a thick cuticle, hairs and sunken stomata on the inner surface. Schematic.", alt: "Two leaf sections: a flat leaf with stomata open to the air, and a rolled leaf with stomata inside, hairs and a thick cuticle.", svg: A.xerophyteLeaf() },
      { id: "d-3.1.5.2-5", title: "Human gas exchange system (gross structure)", status: "reviewed", caption: "Trachea with C-shaped cartilage rings, two bronchi, branching bronchioles and alveoli within the lungs: the five structures named in the specification. Schematic.", alt: "Front view of two lungs with the trachea dividing into bronchi and then bronchioles ending in clusters of alveoli, each labelled.", svg: A.humanSystem() },
      { id: "d-3.1.5.2-6", title: "An alveolus and its capillary", status: "reviewed", caption: "Squamous epithelium one cell thick, capillary endothelium one cell thick, red cells in single file; oxygen diffuses into the blood and carbon dioxide out, each down its own gradient; the diffusion pathway is about 0.5–1 µm. Partial pressures are typical textbook values. Schematic.", alt: "An alveolus with a thin wall, a capillary pressed against it containing red blood cells, and arrows showing oxygen moving into the blood and carbon dioxide out.", svg: A.alveolus() },
      { id: "d-3.1.5.2-7", title: "Thorax at full inspiration", status: "reviewed", caption: "Diaphragm contracted and flattened, ribs raised by the external intercostal muscles, thoracic volume increased. Compare with the Breathing Simulator at expiration. Schematic.", alt: "Section through the thorax showing a flattened diaphragm, raised ribs and expanded lungs.", svg: A.thorax(0.5) },
    ],
    interactives: [
      { kind: "singleCellSim", title: "Single-Celled Exchange", note: "Change the size of a single cell and see why diffusion across its surface is enough, and when it stops being enough." },
      { kind: "trachealExplorer", title: "Insect Tracheal System Explorer", note: "Identify spiracles, tracheae and tracheoles, trace the pathway of oxygen to a muscle fibre and close the spiracles to see the water-loss trade-off." },
      { kind: "leafExplorer", title: "Leaf Cross-Section Explorer", note: "Identify every tissue of a dicot leaf, open and close the stomata, trace CO₂ to a palisade cell and test yourself with the find-the-structure quiz." },
      { kind: "xerophyteCompare", title: "Mesophyte v Xerophyte", note: "Switch on each xerophytic adaptation and see what it does to water loss and to gas exchange." },
      { kind: "alveolusExplorer", title: "Alveolus Explorer", note: "Zoom from the whole system to one alveolus and its capillary; identify the structures and the diffusion pathway." },
      { kind: "breathingSim", title: "Breathing Simulator", note: "Play a breathing cycle or step to inspiration and expiration: diaphragm, ribs, thoracic volume, pressure relative to the atmosphere and airflow change together." },
      { kind: "lungDiseaseData", title: "Lung Disease: Interpreting the Data", note: "Illustrative spirometry and gas-exchange data from a healthy adult and from lungs with narrowed airways, thickened walls or lost surface; interpret, explain and evaluate.", datasets,
        questions: [
          { id: "q-3.1.5.2-ld1", ref: R, stmts: ["3.1.5.2.s7"], type: "short", marks: 3, stem: "Dataset A. Calculate the FEV₁ ÷ FVC ratio for condition X from the table and explain what the value, compared with the healthy adult, tells you about the airways. (3 marks)", scheme: [{ point: "2.4 ÷ 4.4 = 0.55 (accept 0.54–0.55)", marks: 1 }, { point: "Much lower than 0.81: a smaller fraction of the vital capacity can be expelled in one second", marks: 1 }, { point: "So airflow is obstructed / resistance is high (narrowed airways), although total capacity is nearly normal", marks: 1 }], model: "FEV₁ ÷ FVC = 2.4 ÷ 4.4 = 0.55, compared with 0.81 in the healthy adult. The person can still hold almost as much air (FVC 4.4 against 4.8 dm³) but can expel only just over half of it in the first second, which shows that airflow is obstructed: the narrowed, inflamed airways have a high resistance, so expiration is slow.", commonErrors: "Treating a low FEV₁ alone as evidence of small lungs." },
          { id: "q-3.1.5.2-ld2", ref: R, stmts: ["3.1.5.2.s7"], type: "short", marks: 3, stem: "Dataset A. Condition Y has an almost normal FEV₁ ÷ FVC ratio (0.86) but a much lower FVC and tidal volume, and a higher breathing rate. Explain these observations. (3 marks)", scheme: [{ point: "Thickened, stiff alveolar walls reduce the lungs' ability to expand, so less air can be taken in (low FVC and tidal volume)", marks: 1 }, { point: "Airways are not obstructed, so the fraction of the (smaller) capacity expelled in one second is normal", marks: 1 }, { point: "Breathing rate rises to maintain ventilation rate (tidal volume × rate) and oxygen uptake", marks: 1 }], model: "In condition Y the alveolar walls are thickened and stiff, so the lungs cannot expand as far: the forced vital capacity and tidal volume are both reduced. The airways themselves are not narrowed, so the proportion of the vital capacity that can be expelled in the first second is normal or even slightly high. With a small tidal volume the person breathes faster (24 breaths per minute) so that the ventilation rate, tidal volume multiplied by breathing rate, is kept high enough to supply oxygen.", commonErrors: "Saying Y has obstructed airways." },
          { id: "q-3.1.5.2-ld3", ref: R, stmts: ["3.1.5.2.s7", "3.1.5.2.s4"], type: "short", marks: 4, stem: "Dataset B. Conditions Y and Z both lower the arterial pO₂ to about 9 kPa and halve the maximum oxygen uptake, but for different reasons. Use the data and the principles of diffusion to explain each. (4 marks)", scheme: [{ point: "Y: wall thickness 2.4 µm v 0.6 µm: diffusion distance four times greater", marks: 1 }, { point: "So the rate of diffusion of O₂ into the blood is much lower (rate ∝ 1 ÷ thickness); area almost unchanged", marks: 1 }, { point: "Z: surface area 30 m² v 70 m²: less than half the area, so fewer O₂ molecules cross per second; thickness normal", marks: 1 }, { point: "In both, blood leaves the lungs with a lower pO₂ / less saturated (9–9.5 v 13 kPa), so less oxygen is delivered and maximum uptake falls (1.3–1.4 v 3.2 dm³ min⁻¹)", marks: 1 }], model: "Rate of diffusion is proportional to surface area and to the concentration difference, and inversely proportional to the thickness of the barrier. In Y the alveolar wall plus capillary is 2.4 µm thick instead of 0.6 µm, four times the diffusion distance, so oxygen crosses far more slowly even though the area is almost normal. In Z the barrier is normal but the breakdown of alveolar walls has reduced the surface area from 70 to 30 m², so fewer oxygen molecules cross per second. In both cases blood leaves the lungs with a lower pO₂ (9–9.5 kPa against 13 kPa) and less oxygen can be delivered during exercise, which is why the maximum oxygen uptake is less than half the healthy value.", commonErrors: "Not quoting the figures; not naming which factor in Fick's law each condition affects." },
          { id: "q-3.1.5.2-ld4", ref: R, stmts: ["3.1.5.2.s7"], type: "mcq", marks: 1, stem: "Dataset A. The ventilation rate (tidal volume × breathing rate) at rest for the healthy adult is:", options: ["0.5 dm³ min⁻¹", "7.0 dm³ min⁻¹", "14 dm³ min⁻¹", "70 dm³ min⁻¹"], answer: 1, explanation: "0.50 × 14 = 7.0 dm³ min⁻¹." },
          { id: "q-3.1.5.2-ld5", ref: R, stmts: ["3.1.5.2.s7"], type: "short", marks: 2, stem: "Evaluate. A student concludes from Dataset B that 'condition Z is caused by smoking'. Explain why the data do not justify this conclusion, and what further information would be needed. (2 marks)", scheme: [{ point: "The data show the effect on area / uptake, not the cause; no information on exposure, history or controls", marks: 1 }, { point: "Would need data comparing the condition's incidence in smokers and non-smokers (large sample, confounding variables controlled) / evidence of mechanism", marks: 1 }], model: "The table describes what has happened to the alveolar surface and oxygen uptake; it says nothing about what caused the damage. To link the condition to smoking you would need comparative data on how often it occurs in smokers and non-smokers, from a large sample with other factors such as age, occupation and air quality controlled, together with evidence for a mechanism.", commonErrors: "Agreeing with the conclusion because it is plausible." },
        ] },
    ],
    focus: [
      { slot: "alveoli-lm", title: "Lung tissue under the microscope", ref: R, explanation: "<p>In this light micrograph of lung tissue the alveoli appear as the pale spaces, separated by walls so thin that in places only the nuclei of the squamous epithelial cells and of the capillary endothelium can be seen. The red cells in the capillaries lie within a micrometre of the air. Everything the specification asks you to say about the alveolar surface is visible here: a vast number of small sacs (area), walls a single cell thick (distance), and capillaries everywhere (blood supply maintaining the gradient).</p>", question: { id: "q-3.1.5.2-fx1", ref: R, stmts: ["3.1.5.2.s4"], type: "short", marks: 3, stem: "Describe three features visible in a section of lung tissue that make the alveoli an efficient surface for gas exchange, and explain each. (3 marks)", scheme: [{ point: "Many small alveoli: very large total surface area", marks: 1 }, { point: "Walls one flattened cell thick: short diffusion distance", marks: 1 }, { point: "Capillaries pressed against every alveolus: blood carries oxygen away and brings CO₂, maintaining steep gradients", marks: 1 }], model: "The tissue is divided into a huge number of small alveoli, giving a very large total surface area. Their walls consist of a single layer of flattened squamous cells, so the diffusion distance between air and blood is very short. Capillaries run against every alveolar wall, so blood continually removes oxygen and delivers carbon dioxide, keeping the concentration gradients steep.", commonErrors: "Describing features without explaining them." } },
      { slot: "stomata-lm", title: "Stomata on a leaf surface", ref: R, explanation: "<p>This micrograph of a leaf epidermis shows stomata, each a pore between two kidney-shaped guard cells. Unlike the other epidermal cells, guard cells contain chloroplasts, and their walls are thicker on the inner side than the outer, so that when they take up water and swell they bow outwards and the pore opens. The pores are the only route by which carbon dioxide can reach the mesophyll in any quantity, and also the main route by which water vapour leaves; a plant's whole gas-exchange and water balance turns on how far and how long they open.</p>", question: { id: "q-3.1.5.2-fx2", ref: R, stmts: ["3.1.5.2.s2"], type: "short", marks: 3, stem: "Explain why a plant that closes its stomata in dry conditions grows more slowly. (3 marks)", scheme: [{ point: "Closed stomata reduce the diffusion of water vapour out of the leaf (conserving water)", marks: 1 }, { point: "But also reduce the diffusion of CO₂ into the air spaces / mesophyll", marks: 1 }, { point: "So the rate of photosynthesis, and therefore growth, falls: the compromise between gas exchange and water loss", marks: 1 }], model: "Closing the stomata limits the diffusion of water vapour out of the leaf and so conserves water, but the stomata are also the route by which carbon dioxide diffuses into the air spaces and reaches the mesophyll cells. With the pores closed, less carbon dioxide reaches the chloroplasts, photosynthesis slows and the plant makes less sugar for growth. This is the compromise between efficient gas exchange and limiting water loss.", commonErrors: "Saying the plant cannot respire." } },
    ],
    examFocus: `<ul><li>For any surface, write the four principles (area, distance, gradient, moisture) and then say <em>how</em> the organism achieves each: that structure is worth marks even for an organism you have never heard of (statement 6).</li><li>Insects: spiracles → tracheae → tracheoles; diffusion along the tubes; fluid at the tips; ventilation by abdominal movements; spiracle valves and hairs limit water loss.</li><li>Leaves: stomata, guard cells, air spaces, spongy mesophyll surface; water-loss trade-off; xerophyte adaptations explained through the water potential gradient, not just listed.</li><li>Human: name only the five structures; alveolar epithelium one cell thick, capillaries, ventilation and blood flow maintain gradients.</li><li>Breathing: diaphragm and intercostals → volume → pressure relative to atmospheric → airflow. Quiet expiration passive.</li><li>Lung disease data: quote numbers, identify whether area, distance, gradient or airflow is affected, calculate FEV₁/FVC or ventilation rate if asked, evaluate the conclusion.</li></ul>`,
    synoptic: [
      { ref: "3.1.5.1", text: "SA : V explains why single cells manage with their surface and large organisms need these specialised systems." },
      { ref: "3.1.4.2", text: "Fick's law underlies every adaptation on this page." },
      { ref: "3.1.5.3", text: "Haemoglobin in the capillary blood removes oxygen from solution, keeping the alveolar gradient steep." },
      { ref: "3.2.8.1", text: "Transpiration: the water lost through stomata is replaced by the xylem." },
    ],
    quickCheck: [
      { id: "q-3.1.5.2-qc1", ref: R, stmts: ["3.1.5.2.s1"], type: "sequence", marks: 3, stem: "Put the structures in the order oxygen passes through them in an insect.", steps: ["Spiracle", "Trachea", "Tracheole", "Respiring cell"], explanation: "Spiracle → trachea → tracheole → cell." },
      { id: "q-3.1.5.2-qc2", ref: R, stmts: ["3.1.5.2.s3"], type: "mcq", marks: 1, stem: "Which structure is NOT part of the gross structure of the human gas exchange system as listed by OxfordAQA?", options: ["Bronchiole", "Alveolus", "Diaphragm", "Trachea"], answer: 2, explanation: "The diaphragm belongs to the mechanism of breathing; the list is alveoli, bronchioles, bronchi, trachea, lungs." },
      { id: "q-3.1.5.2-qc3", ref: R, stmts: ["3.1.5.2.s5"], type: "gap", marks: 3, stem: "Complete the passage on inspiration.", text: "During inspiration the diaphragm {{1}} and flattens, the external intercostal muscles contract and the ribs move up and out. The volume of the thorax {{2}}, so the pressure in the lungs falls {{3}} atmospheric pressure and air flows in.", answers: { 1: ["contracts"], 2: ["increases", "rises"], 3: ["below"] }, explanation: "Contracts; increases; below." },
      { id: "q-3.1.5.2-qc4", ref: R, stmts: ["3.1.5.2.s2"], type: "mcq", marks: 1, stem: "Sunken stomata reduce water loss because:", options: ["they are closed permanently", "humid air trapped in the pit reduces the water potential gradient between leaf and air", "they let more CO₂ in", "they are larger"], answer: 1, explanation: "Shallower gradient, slower diffusion of water vapour." },
      { id: "q-3.1.5.2-qc5", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "The gas exchange surface of a dicot leaf is:", options: ["the upper epidermis", "the guard cells", "the moist walls of the spongy mesophyll cells bordering the air spaces", "the cuticle"], answer: 2, explanation: "Stomata are the entry; mesophyll walls are the surface." },
    ],
    flashcards: [
      { id: "f-3.1.5.2-1", front: "Four features of an efficient gas exchange surface.", back: "Large surface area; thin (short diffusion distance); steep gradient maintained (ventilation / blood flow); moist (gases dissolve)." },
      { id: "f-3.1.5.2-2", front: "How does a single-celled organism exchange gases?", back: "Diffusion across the whole cell-surface membrane; large SA : V and tiny diffusion distance mean no special surface or transport is needed." },
      { id: "f-3.1.5.2-3", front: "Name the three parts of the insect tracheal system in order.", back: "Spiracles (openings with valves) → tracheae (chitin-ringed tubes) → tracheoles (fine, thin-walled, fluid-filled tips reaching the cells)." },
      { id: "f-3.1.5.2-4", front: "How do gases move through the tracheal system?", back: "Mainly by diffusion along a concentration gradient maintained by respiring cells; in active insects abdominal movements ventilate the tracheae." },
      { id: "f-3.1.5.2-5", front: "Why is the fluid at the tracheole ends important, and what happens during activity?", back: "Oxygen dissolves in it before diffusing into cells; during activity lactate lowers muscle water potential, water is withdrawn and air reaches further (shorter diffusion distance)." },
      { id: "f-3.1.5.2-6", front: "How do insects limit water loss?", back: "Spiracle valves close when demand is low; hairs around spiracles trap humid air; waterproof cuticle elsewhere. Cost: less gas exchange." },
      { id: "f-3.1.5.2-7", front: "Route of CO₂ into a leaf.", back: "Air → stoma (open pore between guard cells) → intercellular air spaces of the spongy mesophyll → dissolves in the moist cell wall → across the membrane into mesophyll cells / chloroplasts." },
      { id: "f-3.1.5.2-8", front: "How do guard cells open a stoma?", back: "They take up water, become turgid and, because their inner walls are thicker, bend apart to open the pore; losing water closes it." },
      { id: "f-3.1.5.2-9", front: "Why do leaves have intercellular air spaces?", back: "Gases diffuse much faster through air than through cells; the spaces connect every mesophyll cell to the stomata and present a large moist surface." },
      { id: "f-3.1.5.2-10", front: "What is a xerophyte?", back: "A plant adapted to living where water is scarce (hot, dry, windy or salty habitats), with adaptations that reduce transpiration." },
      { id: "f-3.1.5.2-11", front: "Explain how sunken stomata and hairs reduce water loss.", back: "They trap still, humid air next to the stomata, reducing the water potential gradient between leaf and air, so water vapour diffuses out more slowly." },
      { id: "f-3.1.5.2-12", front: "List four other xerophytic adaptations.", back: "Thick waxy cuticle; rolled leaves with stomata inside; fewer / smaller stomata or stomata closing by day; small, needle-like leaves or spines (reduced area)." },
      { id: "f-3.1.5.2-13", front: "What is the compromise in terrestrial insects and xerophytes?", back: "A moist, permeable surface needed for gas exchange also loses water; adaptations that limit water loss also slow gas exchange." },
      { id: "f-3.1.5.2-14", front: "Name the five parts of the human gas exchange system required by OxfordAQA.", back: "Trachea, bronchi, bronchioles, alveoli, lungs." },
      { id: "f-3.1.5.2-15", front: "Trachea and bronchi: what keeps them open?", back: "Rings of cartilage (C-shaped in the trachea); bronchioles have smooth muscle but no cartilage." },
      { id: "f-3.1.5.2-16", front: "Essential features of the alveolar epithelium and capillaries.", back: "Squamous epithelium one cell thick; capillary endothelium one cell thick (total ≈ 0.5–1 µm); huge number of alveoli (large area); dense capillary network; moist; ventilation and blood flow maintain gradients." },
      { id: "f-3.1.5.2-17", front: "Which way do O₂ and CO₂ move at the alveolus and why?", back: "O₂ from alveolar air (high pO₂) into blood (low pO₂); CO₂ from blood (high pCO₂) into alveolar air (low pCO₂); each down its own partial-pressure gradient." },
      { id: "f-3.1.5.2-18", front: "How do red blood cells help keep the alveolar gradient steep?", back: "Haemoglobin binds oxygen, keeping dissolved O₂ in the plasma low; cells pass in single file close to the wall; blood flow carries loaded cells away." },
      { id: "f-3.1.5.2-19", front: "Describe inspiration.", back: "Diaphragm contracts and flattens; external intercostals contract, ribs up and out; thoracic volume rises; pressure in lungs falls below atmospheric; air flows in. Active." },
      { id: "f-3.1.5.2-20", front: "Describe quiet expiration.", back: "Diaphragm relaxes and domes up; external intercostals relax, ribs fall down and in; elastic recoil; thoracic volume falls; pressure rises above atmospheric; air flows out. Largely passive." },
      { id: "f-3.1.5.2-21", front: "What is different about forced expiration?", back: "Internal intercostals contract (ribs pulled down and in) and abdominal muscles push the diaphragm up: active; larger, faster volume change." },
      { id: "f-3.1.5.2-22", front: "Define tidal volume, breathing rate and ventilation rate.", back: "Tidal volume: air moved in one breath; breathing rate: breaths per minute; ventilation rate = tidal volume × breathing rate (dm³ min⁻¹)." },
      { id: "f-3.1.5.2-23", front: "What are FVC and FEV₁, and what does a low FEV₁/FVC ratio show?", back: "FVC: maximum air expelled after a full breath in; FEV₁: volume expelled in the first second. A low ratio shows obstructed airways (high resistance to airflow)." },
      { id: "f-3.1.5.2-24", front: "How does thickening of alveolar walls affect gas exchange?", back: "Longer diffusion distance, so a lower rate of diffusion; lungs stiffer, smaller tidal volume, faster breathing; lower arterial pO₂." },
      { id: "f-3.1.5.2-25", front: "How does loss of alveolar walls affect gas exchange?", back: "Smaller surface area (and loss of elastic recoil), so a lower rate of diffusion and difficulty expelling air; lower arterial pO₂, reduced exercise capacity." },
    ],
    questions: [
      { id: "q-3.1.5.2-m1", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "Gas exchange in an insect takes place mainly:", options: ["across the body surface", "in the blood", "at the ends of the tracheoles, directly with the cells", "in the spiracles"], answer: 2, explanation: "Tracheoles deliver gases to the cells; blood is not involved." },
      { id: "q-3.1.5.2-m2", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "The rings of chitin in tracheae:", options: ["absorb oxygen", "prevent the tubes collapsing", "close the spiracles", "produce the fluid at the tracheole ends"], answer: 1, explanation: "Support, like cartilage in the trachea of a mammal." },
      { id: "q-3.1.5.2-m3", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "During vigorous flight, water is withdrawn from the ends of the tracheoles into the muscle. The effect is to:", options: ["reduce water loss", "shorten the diffusion distance for oxygen into the muscle", "close the spiracles", "increase the SA : V of the insect"], answer: 1, explanation: "Air reaches further into the tissue." },
      { id: "q-3.1.5.2-m4", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "In a dicot leaf, most stomata are found:", options: ["in the cuticle", "in the lower epidermis", "in the palisade mesophyll", "in the xylem"], answer: 1, explanation: "Typically the lower epidermis, cooler and shaded." },
      { id: "q-3.1.5.2-m5", ref: R, stmts: ["3.1.5.2.s1"], type: "mcq", marks: 1, stem: "Which feature of a leaf gives the fastest route for CO₂ to reach the mesophyll cells?", options: ["The waxy cuticle", "The continuous intercellular air spaces", "The xylem", "The palisade cell walls"], answer: 1, explanation: "Diffusion through air is far faster than through cells." },
      { id: "q-3.1.5.2-m6", ref: R, stmts: ["3.1.5.2.s2"], type: "mcq", marks: 1, stem: "Which xerophytic adaptation works by reducing the water potential gradient between the leaf and the air?", options: ["Thick cuticle", "Hairs that trap humid air around the stomata", "Small leaves", "Fewer stomata"], answer: 1, explanation: "Humid trapped air has a less negative Ψ, so the gradient is shallower." },
      { id: "q-3.1.5.2-m7", ref: R, stmts: ["3.1.5.2.s4"], type: "mcq", marks: 1, stem: "The walls of the alveoli consist of:", options: ["ciliated epithelium", "squamous (flattened) epithelium one cell thick", "cartilage", "smooth muscle"], answer: 1, explanation: "Short diffusion distance." },
      { id: "q-3.1.5.2-m8", ref: R, stmts: ["3.1.5.2.s4"], type: "mcq", marks: 1, stem: "Which of these maintains the concentration gradient of oxygen across the alveolar wall?", options: ["Thick alveolar walls", "Ventilation and the flow of blood through the capillaries", "Closed bronchioles", "A small number of alveoli"], answer: 1, explanation: "Fresh air and fresh blood keep the difference large." },
      { id: "q-3.1.5.2-m9", ref: R, stmts: ["3.1.5.2.s5"], type: "mcq", marks: 1, stem: "During inspiration:", options: ["the diaphragm relaxes and the thoracic volume falls", "the diaphragm contracts, the thoracic volume rises and the pressure in the lungs falls below atmospheric", "the internal intercostal muscles contract", "the pressure in the lungs rises above atmospheric"], answer: 1, explanation: "Active; volume up, pressure down, air in." },
      { id: "q-3.1.5.2-m10", ref: R, stmts: ["3.1.5.2.s5"], type: "mcq", marks: 1, stem: "Quiet expiration at rest is mainly brought about by:", options: ["contraction of the internal intercostal muscles", "contraction of the diaphragm", "relaxation of the diaphragm and external intercostals with elastic recoil of the lungs", "contraction of the external intercostals"], answer: 2, explanation: "Passive process." },
      { id: "q-3.1.5.2-m11", ref: R, stmts: ["3.1.5.2.s3"], type: "mcq", marks: 1, stem: "Which structure carries air from the trachea into one lung?", options: ["Bronchiole", "Bronchus", "Alveolus", "Oesophagus"], answer: 1, explanation: "Two bronchi, one per lung." },
      { id: "q-3.1.5.2-m12", ref: R, stmts: ["3.1.5.2.s7"], type: "mcq", marks: 1, stem: "A person's tidal volume is 0.4 dm³ and breathing rate 15 breaths min⁻¹. Their ventilation rate is:", options: ["0.027 dm³ min⁻¹", "6 dm³ min⁻¹", "15.4 dm³ min⁻¹", "37.5 dm³ min⁻¹"], answer: 1, explanation: "0.4 × 15 = 6." },
      { id: "q-3.1.5.2-m13", ref: R, stmts: ["3.1.5.2.s7", "3.1.5.2.s4"], type: "mcq", marks: 1, stem: "A disease that thickens the alveolar walls mainly reduces gas exchange by:", options: ["increasing the surface area", "increasing the diffusion distance", "increasing the concentration gradient", "increasing ventilation"], answer: 1, explanation: "Rate ∝ 1 ÷ thickness." },
      { id: "q-3.1.5.2-m14", ref: R, stmts: ["3.1.5.2.s7"], type: "mcq", marks: 1, stem: "Which measurement would best show narrowing of the airways?", options: ["A low FEV₁ ÷ FVC ratio", "A high tidal volume", "A normal breathing rate", "A high arterial pO₂"], answer: 0, explanation: "Obstruction slows expiration." },
      { id: "q-3.1.5.2-m15", ref: R, stmts: ["3.1.5.2.s2"], type: "mcq", marks: 1, stem: "The 'compromise' in xerophytes and terrestrial insects refers to the conflict between:", options: ["growth and reproduction", "efficient gas exchange and limiting water loss", "photosynthesis and respiration", "size and surface area"], answer: 1, explanation: "Spec statement 2." },
      { id: "q-3.1.5.2-g1", ref: R, stmts: ["3.1.5.2.s1"], type: "gap", marks: 4, stem: "Complete the passage.", text: "In an insect, air enters through {{1}} and passes along {{2}}, which are supported by rings of chitin, into fine {{3}} that end in fluid among the cells. Gases move along the system mainly by {{4}}.", answers: { 1: ["spiracles"], 2: ["tracheae"], 3: ["tracheoles"], 4: ["diffusion"] }, explanation: "Spiracles; tracheae; tracheoles; diffusion." },
      { id: "q-3.1.5.2-g2", ref: R, stmts: ["3.1.5.2.s4"], type: "gap", marks: 3, stem: "Complete the passage on the alveoli.", text: "The alveolar wall is a single layer of {{1}} epithelial cells, giving a short diffusion {{2}}. Blood flowing through the capillaries and air moved by {{3}} maintain the concentration gradients.", answers: { 1: ["squamous", "flattened"], 2: ["distance", "pathway"], 3: ["ventilation", "breathing"] }, explanation: "Squamous; distance; ventilation." },
      { id: "q-3.1.5.2-lab1", ref: R, stmts: ["3.1.5.2.s3"], type: "label", drag: true, marks: 5, stem: "Label the five numbered structures of the human gas exchange system.", svg: (() => { const base = A.humanSystem().replace(/<g data-label="[^"]*">.*?<\/g>/gs, ""); const num = (x, y, n) => `<circle cx="${x}" cy="${y}" r="12" fill="#1e3a5f"/><text x="${x}" y="${y + 4}" text-anchor="middle" font-size="12" fill="#fff" font-weight="700">${n}</text>`; return base.replace("</svg>", num(410, 90, 1) + num(440, 190, 2) + num(475, 290, 3) + num(515, 330, 4) + num(250, 230, 5) + "</svg>"); })(), labels: [{ n: 1, answer: "Trachea" }, { n: 2, answer: "Bronchus" }, { n: 3, answer: "Bronchiole" }, { n: 4, answer: "Alveoli" }, { n: 5, answer: "Lung" }], bank: ["Trachea", "Bronchus", "Bronchiole", "Alveoli", "Lung", "Diaphragm", "Oesophagus"] },
      { id: "q-3.1.5.2-match1", ref: R, stmts: ["3.1.5.2.s1"], type: "match", marks: 4, stem: "Match each structure of a leaf to its role in gas exchange.", pairs: [{ left: "Stoma", right: "Pore through which gases enter and leave" }, { left: "Guard cells", right: "Change turgor to open and close the pore" }, { left: "Intercellular air spaces", right: "Fast diffusion pathway through air to every mesophyll cell" }, { left: "Spongy mesophyll cell walls", right: "Moist exchange surface where gases dissolve and cross" }] },
      { id: "q-3.1.5.2-match2", ref: R, stmts: ["3.1.5.2.s5"], type: "match", marks: 4, stem: "Match each change during inspiration to the structure responsible.", pairs: [{ left: "Diaphragm contracts", right: "Flattens, increasing thoracic volume from below" }, { left: "External intercostals contract", right: "Ribs move up and out" }, { left: "Thoracic volume increases", right: "Pressure in the lungs falls below atmospheric" }, { left: "Pressure gradient", right: "Air flows into the lungs" }] },
      { id: "q-3.1.5.2-seq1", ref: R, stmts: ["3.1.5.2.s5"], type: "sequence", marks: 4, stem: "Put the events of quiet expiration in order.", steps: ["Diaphragm and external intercostal muscles relax", "Diaphragm domes upward and ribs move down and in; lungs recoil elastically", "Volume of the thoracic cavity decreases", "Pressure in the lungs rises above atmospheric and air flows out"], explanation: "Relax → volume down → pressure up → air out." },
      { id: "q-3.1.5.2-d1", ref: R, stmts: ["3.1.5.2.s2"], type: "short", marks: 3, stem: "Data. In an experiment, the rate of water loss from leaves of two species was measured in still air and in moving air (illustrative): Species 1 (stomata on a flat surface): still 2.1, moving 6.8 mg g⁻¹ h⁻¹. Species 2 (stomata sunken, surface hairy): still 1.0, moving 1.6 mg g⁻¹ h⁻¹. Explain why moving air increased water loss in both species, and why the increase was much smaller in species 2. (3 marks)", scheme: [{ point: "Moving air removes the humid air next to the leaf, steepening the water potential gradient, so diffusion of water vapour out is faster", marks: 1 }, { point: "In species 2 the pits and hairs retain a layer of still humid air even when the air outside moves", marks: 1 }, { point: "So the gradient stays shallow and the rate rises only a little (1.6 v 1.0, compared with 6.8 v 2.1)", marks: 1 }], model: "Moving air sweeps away the layer of humid air that forms next to the stomata, so the water potential gradient between the leaf and the air becomes steeper and water vapour diffuses out faster: in species 1 the rate more than tripled. In species 2 the sunken stomata and hairs hold a layer of still, humid air that the wind cannot easily remove, so the gradient stays shallow and the rate increases only from 1.0 to 1.6.", commonErrors: "Not referring to the gradient." },
      { id: "q-3.1.5.2-s1", ref: R, stmts: ["3.1.5.2.s1", "3.1.5.2.s2"], type: "short", marks: 4, stem: "Explain how the tracheal system of an insect is adapted for efficient gas exchange, and how the insect limits water loss. (4 marks)", scheme: [{ point: "Many fine tracheoles give a large surface area and reach every cell: short diffusion distance", marks: 1 }, { point: "Tracheole walls thin / permeable; gases dissolve in fluid at the ends; gradient maintained by respiration (and ventilation by abdominal movement)", marks: 1 }, { point: "Spiracles can be closed by valves / open only when needed", marks: 1 }, { point: "Hairs round spiracles trap humid air; waterproof cuticle elsewhere", marks: 1 }], model: "The tracheae branch into very many fine tracheoles that run between and into the cells, providing a large surface and a diffusion distance of only a few micrometres. The tracheole walls are thin and permeable and the gases dissolve in the fluid at their ends; respiration in the cells keeps the oxygen gradient steep, and in active insects abdominal movements ventilate the tubes. Water loss is limited by valves that close the spiracles when oxygen demand is low, by hairs around the spiracles that trap humid air, and by the waterproof cuticle over the rest of the body.", commonErrors: "Saying blood carries oxygen to insect tissues." },
      { id: "q-3.1.5.2-s2", ref: R, stmts: ["3.1.5.2.s1"], type: "short", marks: 4, stem: "Describe how carbon dioxide reaches the chloroplast of a palisade cell from the air outside a leaf, and explain two ways the leaf is adapted to speed this up. (4 marks)", scheme: [{ point: "CO₂ diffuses through an open stoma (between guard cells) down a gradient maintained by photosynthesis", marks: 1 }, { point: "Through the intercellular air spaces of the spongy mesophyll, dissolves in the moist cell wall and diffuses across the membrane into the cell / chloroplast", marks: 1 }, { point: "Adaptation: large area of thin, moist mesophyll walls exposed to the air spaces", marks: 1 }, { point: "Adaptation: thin flat leaf / air-space network gives a short diffusion distance; many stomata", marks: 1 }], model: "Carbon dioxide diffuses from the air through an open stoma, the pore between two guard cells, down a concentration gradient maintained by photosynthesis in the mesophyll. It diffuses through the intercellular air spaces of the spongy mesophyll, dissolves in the film of water on the thin cell walls, crosses the cell-surface membrane and diffuses to the chloroplasts. The leaf speeds this up with a very large area of thin, moist mesophyll cell walls bordering the air spaces, and with a thin, flat shape and continuous air spaces that keep the diffusion distance short.", commonErrors: "Saying CO₂ enters through the cuticle." },
      { id: "q-3.1.5.2-s3", ref: R, stmts: ["3.1.5.2.s4"], type: "short", marks: 4, stem: "Explain how the structure of the alveoli and their capillaries makes gas exchange efficient. (4 marks)", scheme: [{ point: "Large number of alveoli: very large total surface area", marks: 1 }, { point: "Squamous epithelium and capillary endothelium each one cell thick: short diffusion distance", marks: 1 }, { point: "Dense capillary network with blood flow carrying oxygenated blood away and bringing CO₂: maintains gradients", marks: 1 }, { point: "Ventilation replaces alveolar air, keeping pO₂ high and pCO₂ low; moist surface for gases to dissolve", marks: 1 }], model: "The lungs contain an enormous number of alveoli, giving a very large total surface area. Each alveolus is lined with squamous epithelium one flattened cell thick and is wrapped in capillaries whose walls are also one cell thick, so the diffusion distance between air and blood is under a micrometre. The constant flow of blood removes oxygenated blood and delivers carbon dioxide, and ventilation keeps replacing the alveolar air, so the concentration gradients for both gases stay steep. The surface is moist, allowing the gases to dissolve before diffusing across.", commonErrors: "Omitting the role of blood flow and ventilation in maintaining gradients." },
      { id: "q-3.1.5.2-s4", ref: R, stmts: ["3.1.5.2.s5"], type: "short", marks: 3, stem: "Describe the roles of the diaphragm and the intercostal muscles in inspiration, and explain why air enters the lungs. (3 marks)", scheme: [{ point: "Diaphragm contracts and flattens; external intercostal muscles contract and move the ribs up and out", marks: 1 }, { point: "Volume of the thoracic cavity increases", marks: 1 }, { point: "Pressure in the lungs falls below atmospheric pressure, so air moves in down the pressure gradient", marks: 1 }], model: "The diaphragm contracts and flattens, and the external intercostal muscles contract, pulling the ribs upwards and outwards. Both changes increase the volume of the thoracic cavity. Because the same amount of air now occupies a larger volume, the pressure in the lungs falls below atmospheric pressure and air moves into the lungs down the pressure gradient.", commonErrors: "'The lungs suck air in'; naming the internal intercostals." },
      { id: "q-3.1.5.2-s5", ref: R, stmts: ["3.1.5.2.s6"], type: "short", marks: 3, stem: "Unfamiliar surface. A marine worm lives in a burrow and has feathery gills extended into the water, which it waves to and fro. Use the principles of gas exchange to explain three features of these gills. (3 marks)", scheme: [{ point: "Feathery / branched: large surface area for diffusion", marks: 1 }, { point: "Thin-walled with blood close to the surface: short diffusion distance (and blood carries oxygen away, maintaining the gradient)", marks: 1 }, { point: "Waving moves fresh water over the gills (ventilation), replacing oxygen-depleted water and maintaining the concentration gradient", marks: 1 }], model: "The feathery branching gives the gills a large surface area, and their thin walls with blood vessels close beneath them give a short diffusion distance, while the blood carries absorbed oxygen away. Waving the gills ventilates them: it replaces the water next to the surface, which would otherwise become depleted of oxygen, so the concentration gradient stays steep.", commonErrors: "Not linking each feature to a principle." },
      { id: "q-3.1.5.2-s6", ref: R, stmts: ["3.1.5.2.s6", "3.1.4.2.s3"], type: "short", marks: 3, stem: "Unfamiliar surface. Lungless salamanders have no lungs and no gills as adults; they take in oxygen across their skin and the lining of the mouth. Their skin is very thin, is kept moist by mucus, and has a dense network of capillaries just below the surface. Use the principles of gas exchange to explain how each of these three features helps the salamander to take in enough oxygen. (3 marks)", scheme: [{ point: "Thin skin: short diffusion distance between the air and the blood", marks: 1 }, { point: "Moist surface: oxygen dissolves in the water film before it diffuses across the cells", marks: 1 }, { point: "Dense capillary network: blood flow carries absorbed oxygen away (and brings blood close to the surface), maintaining a steep concentration gradient (credit: a large area of contact between skin and blood)", marks: 1 }], model: "The skin is very thin, so the diffusion distance between the air and the blood in the capillaries is short and oxygen crosses quickly. The mucus keeps the surface moist, so oxygen can dissolve before it diffuses across the cell membranes of the skin. The dense network of capillaries just below the surface brings blood close to the air over a large area, and the flowing blood carries the oxygen away as soon as it arrives, so the concentration gradient between the air and the blood stays steep.", commonErrors: "Describing the features without linking each to a factor in the rate of diffusion (distance, gradient, area); saying the mucus 'traps' oxygen." },
      { id: "q-3.1.5.2-e1", ref: R, stmts: ["3.1.5.2.s1", "3.1.5.2.s2"], type: "extended", marks: 6, stem: "Extended response. Compare the ways in which the tracheal system of an insect and the leaf of a xerophytic plant achieve gas exchange while limiting water loss. (6 marks)", scheme: [{ point: "Both have internal, moist exchange surfaces reached through small openings in a waterproof outer layer (spiracles in the cuticle; stomata in the waxy cuticle)", marks: 1 }, { point: "Both rely on diffusion down gradients maintained by the cells (respiration in the insect; photosynthesis in the leaf)", marks: 1 }, { point: "Insect: tracheae and tracheoles deliver gases directly to cells; leaf: air spaces and spongy mesophyll surface", marks: 1 }, { point: "Both control the openings: spiracle valves close when demand is low; guard cells close stomata when water is short", marks: 1 }, { point: "Xerophyte extras: sunken stomata, hairs, rolled leaves trap humid air and reduce the water potential gradient; thick cuticle; small leaves", marks: 1 }, { point: "In both, limiting water loss reduces the rate of gas exchange: a compromise (the insect opens its spiracles and ventilates when demand rises; the xerophyte grows more slowly)", marks: 1 }], levels: "Level 3 (5–6): a genuine comparison, with similarities and differences, mechanisms explained in terms of gradients and the compromise stated. Level 2 (3–4): descriptions of both with some comparison. Level 1 (1–2): fragments.", model: "Both organisms keep their moist exchange surfaces inside a waterproof covering and reach them through small openings: spiracles in the insect's cuticle and stomata in the leaf's waxy cuticle. In both, gases move by diffusion down gradients maintained by the cells, respiration in the insect and photosynthesis in the leaf. The insect delivers air directly to its cells along tracheae and tracheoles whose fluid-filled ends lie among the muscle fibres, whereas the leaf lets gases diffuse through intercellular air spaces to the large moist surface of the spongy mesophyll. Both control the openings: spiracle valves close when oxygen demand is low, and guard cells close the stomata when water is short. The xerophyte adds structural adaptations, sunken stomata, hairs and rolled leaves that trap humid air and reduce the water potential gradient, together with a thick cuticle and small leaves. In both cases the cost is a reduced rate of gas exchange; the insect opens its spiracles and ventilates by abdominal movements when demand rises, and the xerophyte usually grows more slowly.", commonErrors: "Describing one organism only; listing adaptations without the mechanism." },
    ],
  };
})();
